package dev.veltraph.client.builder;
import dev.veltraph.client.config.*;
import dev.veltraph.client.gui.MenuSnapshot;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class Source95NativeChatJournalTest {
 private Source95AcquisitionBinding binding(){return new Source95AcquisitionBinding(BuilderCropType.WHEAT,"Seeds","@vanilla",Set.of("Seeds"),Map.of("instant","Instant","stack","Stack"),500,100,30000);}
 private MenuSnapshot menu(int revision){return new MenuSnapshot(4,"Seeds",List.of(new MenuSnapshot.Slot(13,"Stack",List.of("Item: Seeds","Amount: 64x","Price: 192 Coins"),false,"minecraft:paper",1,false)),revision);}
 private Source95AcquisitionAuthority.Scope scope(Object connection){return new Source95AcquisitionAuthority.Scope(new Object(),new Object(),connection,new Object(),new Object(),new Object(),4,1);}
 private Source95ChatReceipts.Scope chat(Source95AcquisitionAuthority.Scope s){return new Source95ChatReceipts.Scope(s.player(),s.world(),s.connection(),s.menu(),s.screen(),s.menuId());}
 private Source95BazaarLeg leg(int before){var leg=new Source95BazaarLeg(new Source95PurchaseChooser.Choice(Source95PurchaseChooser.Kind.STACK,64),before,true);leg.tick(binding(),menu(1),false,before,500);return leg;}
 @Test void identicalLegitimateTextUsesDistinctNativeEventsAndConsumedFirstCannotReuse(){Object c=new Object(),token=new Object();var scope=scope(c);Source95ChatReceipts.attach(c,token);try{long floor1=Source95ChatReceipts.floor();var a=leg(127);Source95ChatReceipts.received(c,chat(scope),"[Bazaar] Bought 64x Seeds for 192 coins!",false);var first=Source95ChatReceipts.after(c,token,floor1,scope).getFirst();a.message(first,binding());a.tick(binding(),menu(2),false,191,500);assertEquals(Source95BazaarLeg.State.COMPLETE,a.state());assertTrue(Source95ChatReceipts.consume(c,token,first.eventId()));assertFalse(Source95ChatReceipts.consume(c,token,first.eventId()));long floor2=Source95ChatReceipts.floor();var b=leg(191);assertTrue(Source95ChatReceipts.after(c,token,floor2,scope).isEmpty());b.tick(binding(),menu(2),false,255,308);assertEquals(Source95BazaarLeg.State.ACK,b.state());Source95ChatReceipts.received(c,chat(scope),"[Bazaar] Bought 64x Seeds for 192 coins!",false);var second=Source95ChatReceipts.after(c,token,floor2,scope).getFirst();assertTrue(second.eventId()>first.eventId());b.message(second,binding());b.tick(binding(),menu(3),false,255,308);assertEquals(Source95BazaarLeg.State.COMPLETE,b.state());}finally{Source95ChatReceipts.detach(c,token);}}
 @Test void multipleMatchingNativeEventsInsidePendingLegQuarantineAmbiguity(){Object c=new Object(),token=new Object();var scope=scope(c);Source95ChatReceipts.attach(c,token);try{long floor=Source95ChatReceipts.floor();var a=leg(191);Source95ChatReceipts.received(c,chat(scope),"[Bazaar] Bought 64x Seeds for 192 coins!",false);Source95ChatReceipts.received(c,chat(scope),"[Bazaar] Bought 64x Seeds for 192 coins!",false);for(var r:Source95ChatReceipts.after(c,token,floor,scope))a.message(r,binding());assertEquals(Source95BazaarLeg.State.FAILED,a.state());}finally{Source95ChatReceipts.detach(c,token);}}
 @Test void pickupNoFreshMessageWrongScopeAndOverlayNeverSupplyAnAcknowledgement(){Object c=new Object(),token=new Object();var scope=scope(c);Source95ChatReceipts.attach(c,token);try{long floor=Source95ChatReceipts.floor();var a=leg(191);a.tick(binding(),menu(2),false,255,308);assertEquals(Source95BazaarLeg.State.ACK,a.state());Source95ChatReceipts.received(c,new Source95ChatReceipts.Scope(scope.player(),scope.world(),c,new Object(),scope.screen(),4),"[Bazaar] Bought 64x Seeds for 192 coins!",false);Source95ChatReceipts.received(c,chat(scope),"[Bazaar] Bought 64x Seeds for 192 coins!",true);assertTrue(Source95ChatReceipts.after(c,token,floor,scope).isEmpty());}finally{Source95ChatReceipts.detach(c,token);}}
 @Test void loneNewDuplicateEventIsOnlyChronologyNotAProvedServerTransaction(){Object c=new Object(),token=new Object();var scope=scope(c);Source95ChatReceipts.attach(c,token);try{long floor=Source95ChatReceipts.floor();Source95ChatReceipts.received(c,chat(scope),"[Bazaar] Bought 64x Seeds for 192 coins!",false);assertEquals(1,Source95ChatReceipts.after(c,token,floor,scope).size());/* Native protocol has no server transaction ID: this event may be new purchase or delayed duplicate. The actual port STILL needs its fresh issued click and independent exact delta64; no causal-server-ID guarantee is asserted. */}finally{Source95ChatReceipts.detach(c,token);}}
}
